
import type { Metadata } from "next";
import Home from "@/components/Home";
import { getCategories } from "@/lib/getCategories";
import { cleanWpmString } from "@/lib/metadata";
import {
  getYoastSEO,
  getYoastRobots,
} from "@/lib/yoast";

const FRONTEND_URL = "https://www.jcblautomoto.com";

// Fetch the LocalBusiness schema generated by the WordPress PHP snippet.
async function getLocalBusinessSchema() {
  try {
    const response = await fetch(
      "https://api.jcblautomoto.com/",
      {
        next: { revalidate: 3600 },
      }
    );

    if (!response.ok) {
      console.error(
        "LocalBusiness schema fetch failed:",
        response.status
      );
      return null;
    }

    const html = await response.text();

    const scripts = [
      ...html.matchAll(
        /<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi
      ),
    ];

    for (const match of scripts) {
      try {
        const schema = JSON.parse(match[1]);

        const graph = Array.isArray(schema["@graph"])
          ? schema["@graph"]
          : [schema];

        const localBusiness = graph.find((item: any) => {
          const type = item?.["@type"];

          return (
            type === "LocalBusiness" ||
            (Array.isArray(type) &&
              type.includes("LocalBusiness")) ||
            item?.["@id"]?.endsWith("#localbusiness")
          );
        });

        if (localBusiness) {
          return localBusiness;
        }
      } catch {
        continue;
      }
    }

    console.error(
      "LocalBusiness schema not found in WordPress homepage HTML."
    );

    return null;
  } catch (error) {
    console.error(
      "LocalBusiness schema fetch error:",
      error
    );

    return null;
  }
}

// Existing JCBL Auto Moto Organization schema.
const organizationSchema = {
  "@type": "Organization",
  "@id": `${FRONTEND_URL}/#organization`,
  "name": "JCBL Auto Moto",
  "url": `${FRONTEND_URL}/`,
  "logo": {
    "@type": "ImageObject",
    "url": `${FRONTEND_URL}/icon.png`,
  },
  "description": "JCBL India Auto Moto",
  "sameAs": [],
};

export async function generateMetadata(): Promise<Metadata> {
  const fallbackCanonical = `${FRONTEND_URL}/`;

  // Get homepage robots directives from custom WordPress API.
  const robots = await getYoastRobots("home");

  try {
    const seo = await getYoastSEO(
      "https://api.jcblautomoto.com/"
    );

    if (!seo?.json) {
      return {
        title: "JCBL Auto Moto",
        description: "",
        alternates: {
          canonical: fallbackCanonical,
        },
        robots,
      };
    }

    // Clean multilingual tags from Yoast SEO fields.
    const cleanDescription = cleanWpmString(
      seo.json.description
    );

    const cleanOgTitle =
      cleanWpmString(seo.json.og_title) ||
      cleanWpmString(seo.json.title) ||
      "JCBL Auto Moto";

    const cleanOgDescription =
      cleanWpmString(seo.json.og_description) ||
      cleanDescription;

    const cleanTwitterDescription =
      cleanWpmString(seo.json.twitter_description) ||
      cleanOgDescription ||
      cleanDescription;

    return {
      title: seo.json.title || "JCBL Auto Moto",

      description: cleanDescription,

      alternates: {
        canonical: fallbackCanonical,
      },

      // Robots directives controlled by Yoast Advanced.
      robots,

      openGraph: {
        title: cleanOgTitle,
        description: cleanOgDescription,
        url: fallbackCanonical,
        siteName:
          seo.json.og_site_name ||
          "JCBL Auto Moto",
        type: "website",
      },

      twitter: {
        card:
          seo.json.twitter_card ||
          "summary_large_image",
        description: cleanTwitterDescription,
      },
    };

  } catch (error) {
    console.error(
      "Homepage SEO fetch failed:",
      error
    );

    return {
      title: "JCBL Auto Moto",
      description: "",
      alternates: {
        canonical: fallbackCanonical,
      },
      robots,
    };
  }
}

export default async function Page() {
  const [categories, localBusinessSchema] = await Promise.all([
    getCategories(),
    getLocalBusinessSchema(),
  ]);

  // Combine LocalBusiness and Organization schemas.
  const homepageBusinessSchema = localBusinessSchema
    ? {
        "@context": "https://schema.org",
        "@graph": [
          localBusinessSchema,
          organizationSchema,
        ],
      }
    : null;

  return (
    <>
      {homepageBusinessSchema && (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: JSON.stringify(
              homepageBusinessSchema
            ).replace(/</g, "\\u003c"),
          }}
        />
      )}

      <Home categories={categories} />
    </>
  );
}
